  response: ["cards"], store: ["cards"], compiler: ["cards"], language: ["cards"],
  contour: ["cards"], git: ["cards"], acceptance: ["cards", "wait", "compiler"],
  processor: ["cards", "wait", "compiler"], planner: ["cards", "contour", "language"],
